import pandas as pd
from typing import Dict

def run(inputs: Dict[str, pd.DataFrame]) -> Dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Build a dict of current state: order_id -> (status, amount, last_seq)
    state = {}
    if not target_state.empty:
        for _, row in target_state.iterrows():
            order_id = int(row["order_id"])
            state[order_id] = {
                "status": row["status"],
                "amount": row["amount"],
                "last_seq": int(row["last_seq"])
            }

    # Track which orders existed in target_state initially (for tombstone eligibility)
    orders_in_target = set(state.keys())

    # Track orders that were created or modified in this batch
    orders_touched = set()

    # Track the last operation for each order (for tombstone determination)
    last_op = {}  # order_id -> (op, seq)

    # Deduplicate events by seq per order and sort by seq
    event_dict = {}  # (order_id, seq) -> event row
    for _, row in cdc_events.iterrows():
        order_id = int(row["order_id"])
        seq = int(row["seq"])
        key = (order_id, seq)
        # Keep only the first occurrence (deduplicate)
        if key not in event_dict:
            event_dict[key] = row

    # Sort events by seq globally
    sorted_events = sorted(event_dict.values(), key=lambda x: int(x["seq"]))

    # Apply events in seq order
    for _, event in sorted_events:
        order_id = int(event["order_id"])
        seq = int(event["seq"])
        op = event["op"]

        # Replay guard: skip if order exists in state and seq <= last_seq
        if order_id in state:
            if seq <= state[order_id]["last_seq"]:
                continue

        orders_touched.add(order_id)

        if op in ('I', 'U'):
            if order_id in state:
                # Update existing row
                if op == 'U' and pd.isna(event["amount"]):
                    # Update with NULL amount: keep existing amount
                    state[order_id]["status"] = event["status"]
                    # amount unchanged
                else:
                    # Update or Insert: set amount from event
                    state[order_id]["status"] = event["status"]
                    state[order_id]["amount"] = event["amount"]
            else:
                # Create new row
                state[order_id] = {
                    "status": event["status"],
                    "amount": event["amount"]
                }
            state[order_id]["last_seq"] = seq
            last_op[order_id] = (op, seq)

        elif op == 'D':
            # Delete: remove from state
            if order_id in state:
                del state[order_id]
            last_op[order_id] = (op, seq)

    # Build new_state
    new_state_rows = []
    for order_id in sorted(state.keys()):
        entry = state[order_id]
        new_state_rows.append({
            "order_id": order_id,
            "status": entry["status"],
            "amount": entry["amount"],
            "last_seq": entry["last_seq"]
        })

    new_state_df = pd.DataFrame(new_state_rows) if new_state_rows else pd.DataFrame(
        columns=["order_id", "status", "amount", "last_seq"]
    )
    if not new_state_df.empty:
        new_state_df["order_id"] = new_state_df["order_id"].astype("int64")
        new_state_df["last_seq"] = new_state_df["last_seq"].astype("int64")

    # Build tombstones: orders that HAD a row in target_state and last op is 'D'
    tombstone_rows = []
    for order_id in sorted(orders_in_target):
        if order_id in last_op:
            op, seq = last_op[order_id]
            if op == 'D':
                tombstone_rows.append({
                    "order_id": order_id,
                    "deleted_seq": seq
                })

    tombstones_df = pd.DataFrame(tombstone_rows) if tombstone_rows else pd.DataFrame(
        columns=["order_id", "deleted_seq"]
    )
    if not tombstones_df.empty:
        tombstones_df["order_id"] = tombstones_df["order_id"].astype("int64")
        tombstones_df["deleted_seq"] = tombstones_df["deleted_seq"].astype("int64")

    return {
        "new_state": new_state_df,
        "tombstones": tombstones_df
    }
